import numpy as np
from scipy.optimize import minimize
import time

def official_score(h):
    n = len(h)
    dx = 2.0 / n
    return float(np.correlate(h, 1.0 - h, mode='full').max() * dx)

def manual_correlate(h):
    n = len(h)
    result = np.zeros(2 * n - 1)
    for p in range(2 * n - 1):
        s = p - (n - 1)
        if s >= 0:
            m = np.arange(n - s)
            result[p] = np.dot(h[m + s], 1.0 - h[m])
        else:
            t = -s
            m = np.arange(n - t)
            result[p] = np.dot(h[m], 1.0 - h[m + t])
    return result

def manual_grad(h):
    n = len(h)
    grad = np.zeros((2 * n - 1, n))
    for p in range(2 * n - 1):
        s = p - (n - 1)
        if s >= 0:
            for j in range(n):
                g = 0.0
                if s <= j:
                    g += (1.0 - h[j - s])
                if j < n - s:
                    g -= h[j + s]
                grad[p, j] = g
        else:
            t = -s
            for j in range(n):
                g = 0.0
                if j < n - t:
                    g += (1.0 - h[j + t])
                if t <= j:
                    g -= h[j - t]
                grad[p, j] = g
    return grad

def make_feasible(z):
    n = len(z)
    target = n / 2.0
    z = np.asarray(z, dtype=float).copy()
    z = np.clip(z, -1.0, 2.0)
    lo = -2.0
    hi = 2.0
    for _ in range(80):
        mid = (lo + hi) / 2.0
        s = np.sum(np.clip(z + mid, 0.0, 1.0))
        if s < target:
            lo = mid
        else:
            hi = mid
    h = np.clip(z + (lo + hi) / 2.0, 0.0, 1.0)
    residual = target - np.sum(h)
    if abs(residual) > 1e-13:
        if residual > 0:
            order = np.argsort(1.0 - h)
            for idx in order:
                add = min(residual, 1.0 - h[idx])
                if add <= 0:
                    break
                h[idx] += add
                residual -= add
                if abs(residual) < 1e-15:
                    break
        else:
            order = np.argsort(h)
            for idx in order:
                sub = min(-residual, h[idx])
                if sub <= 0:
                    break
                h[idx] -= sub
                residual += sub
                if abs(residual) < 1e-15:
                    break
    h = np.clip(h, 0.0, 1.0)
    return h

def smooth_obj(x, beta):
    n = len(x)
    dx = 2.0 / n
    vals = manual_correlate(x) * dx
    cmax = vals.max()
    shifted = beta * (vals - cmax)
    logsum = np.log(np.sum(np.exp(shifted)))
    return cmax + logsum / beta

def smooth_grad(x, beta):
    n = len(x)
    dx = 2.0 / n
    vals = manual_correlate(x) * dx
    cmax = vals.max()
    shifted = beta * (vals - cmax)
    w = np.exp(shifted)
    ws = w.sum()
    if ws < 1e-300:
        w = np.ones(len(vals)) / len(vals)
    else:
        w /= ws
    grads = manual_grad(x)
    return dx * (w @ grads)

