def mm_obj(z):
    return z[-1]

def mm_obj_jac(z):
    g = np.zeros(len(z))
    g[-1] = 1.0
    return g

def mm_ineq_fun(z):
    n = len(z) - 1
    dx = 2.0 / n
    h = z[:n]
    theta = z[-1]
    vals = manual_correlate(h) * dx
    return theta - vals

def mm_ineq_jac(z):
    n = len(z) - 1
    dx = 2.0 / n
    h = z[:n]
    grads = manual_grad(h)
    J = -dx * grads
    J = np.hstack([J, np.ones((J.shape[0], 1))])
    return J

def mm_eq_fun(z):
    n = len(z) - 1
    return np.sum(z[:n]) - n / 2.0

def mm_eq_jac(z):
    n = len(z) - 1
    g = np.zeros(n + 1)
    g[:n] = 1.0
    return g

def try_smooth(h0, beta, maxiter=150, ftol=1e-13):
    n = len(h0)
    bounds = [(0.0, 1.0)] * n
    cons = [{'type': 'eq', 'fun': smooth_eq_fun, 'jac': smooth_eq_jac}]
    try:
        res = minimize(smooth_obj, h0, args=(beta,), jac=smooth_grad,
                       method='SLSQP', bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        if res.x is not None and np.all(np.isfinite(res.x)):
            h_new = make_feasible(res.x)
            sc = official_score(h_new)
            if np.isfinite(sc):
                return h_new, sc
    except Exception:
        pass
    return None, None

def try_direct(h0, maxiter=200, ftol=1e-11):
    n = len(h0)
    theta0 = official_score(h0) + 1e-8
    z0 = np.concatenate([h0, [theta0]])
    bounds = [(0.0, 1.0)] * n + [(0.0, 2.0)]
    cons = [
        {'type': 'ineq', 'fun': mm_ineq_fun, 'jac': mm_ineq_jac},
        {'type': 'eq', 'fun': mm_eq_fun, 'jac': mm_eq_jac}
    ]
    try:
        res = minimize(mm_obj, z0, jac=mm_obj_jac, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        if res.x is not None and np.all(np.isfinite(res.x)):
            h_new = make_feasible(res.x[:n])
            sc = official_score(h_new)
            if np.isfinite(sc):
                return h_new, sc
    except Exception:
        pass
    return None, None

def interpolate_to(h_src, n_tgt):
    n_src = len(h_src)
    src_c = (np.arange(n_src) + 0.5) * (2.0 / n_src)
    tgt_c = (np.arange(n_tgt) + 0.5) * (2.0 / n_tgt)
    h_int = np.interp(tgt_c, src_c, h_src)
    return make_feasible(h_int)

def anti_sym(h):
    h_new = 1.0 - h[::-1].copy()
    return make_feasible(h_new)

